// Command growscada_device_simulator is a Device Gateway: it acts for the
// Device its Device Token names, in one Environment, writes Tag values
// generated by patterns to a GrowSCADA server and serves a control API.
package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"time"

	"github.com/alexflint/go-arg"
	"github.com/kipitix/gracedown"

	"github.com/kipitix/growscada/internal/apiclient"
	"github.com/kipitix/growscada/internal/devicelink"
	"github.com/kipitix/growscada/internal/devicesim"
)

type simulatorArgs struct {
	Config  string `arg:"--config,required" help:"YAML config of the simulated device"`
	Server  string `arg:"--server,env:DEVSIM_SERVER" help:"GrowSCADA REST API URL; overrides the config"`
	Token   string `arg:"--token,env:DEVSIM_TOKEN" help:"Device Token; overrides the config"`
	Control string `arg:"--control" help:"control API listen address; overrides the config"`
}

type slogAdapter struct{}

func (slogAdapter) Println(v ...any) {
	slog.Info(fmt.Sprint(v...))
}

func main() {
	var args simulatorArgs
	arg.MustParse(&args)

	cfg, err := readConfig(args.Config, args)
	if err != nil {
		slog.Error("Config error", "error", err)
		if errors.Is(err, os.ErrNotExist) {
			os.Exit(gracedown.ExitNoInput)
		}
		os.Exit(gracedown.ExitConfig)
	}

	// Create a graceful shutdown manager
	gracedownManager := gracedown.NewManager(gracedown.WithLogger(slogAdapter{}))

	// One client for the REST calls, one carrying the Gateway's token for
	// them too: a Device acts with its token, and the token names its project.
	api := apiclient.New(cfg.Server, &http.Client{Timeout: 10 * time.Second},
		devicelink.WarnOlderServer(slog.Default())).WithDeviceToken(cfg.Token)
	link := devicelink.NewRESTLink(api, cfg.Token)
	gateway := devicesim.NewGateway(api, cfg.Environment)
	device := devicesim.New(cfg, link, gateway, devicesim.Options{})

	// INTERFACE COMPONENTS
	// The control API comes up first: it answers while the Device waits for
	// the server.
	listener, err := net.Listen("tcp", cfg.Control)
	if err != nil {
		slog.Error("Control API listen error", "address", cfg.Control, "error", err)
		emergencyExit(gracedownManager, gracedown.ExitUnavailable)
	}
	controlServer := &http.Server{Handler: device.Handler()}
	// Register the control API shutdown handler
	gracedownManager.RegisterInterface("Control API HTTP Server", 5*time.Second, func(ctx context.Context) error {
		return controlServer.Shutdown(ctx)
	})
	// Start the control API in a separate goroutine
	go func() {
		slog.Info("Control API starting", "address", listener.Addr().String())
		if err := controlServer.Serve(listener); err != nil && !errors.Is(err, http.ErrServerClosed) {
			slog.Error("Control API error", "error", err)
			emergencyExit(gracedownManager, gracedown.ExitUnavailable)
		}
	}()

	// INFRASTRUCTURE COMPONENTS
	// The Device and its link to the server: stopped after the control API,
	// so no control call races the shutdown; in-flight writes may finish.
	runCtx, stopDevice := context.WithCancel(context.Background())
	deviceDone := make(chan struct{})
	gracedownManager.RegisterInfrastructure("Device", 10*time.Second, func(ctx context.Context) error {
		stopDevice()
		select {
		case <-deviceDone:
			return nil
		case <-ctx.Done():
			return ctx.Err()
		}
	})
	// Run the Device in a separate goroutine: it reads its configuration from
	// the server (waiting for it as long as it takes), then writes the tags.
	go func() {
		slog.Info("Device starting", "server", cfg.Server, "environment", cfg.Environment, "tags", len(cfg.Tags), "running", device.Status().Running)
		err := device.Run(runCtx)
		close(deviceDone) // before an emergency exit, whose Device hook waits for it
		if err != nil {
			slog.Error("Device error", "error", err)
			emergencyExit(gracedownManager, exitCode(err))
		}
	}()

	// Wait for shutdown signal
	err = gracedownManager.WaitForSignalAndShutdown()
	if err != nil {
		slog.Error("Error on graceful shutdown", "error", err)
		os.Exit(gracedown.ExitFailure)
	}

	slog.Info("Device simulator stopped gracefully")

	os.Exit(gracedown.ExitSuccess)
}

// exitCode maps a Device error to the process's exit code (task 34, part A,
// "Коды выхода"):
//
//   - a token the server refuses (401) is ExitNoPerm: the Gateway cannot fix
//     its credentials. A 403 never gets here — a refused configuration is
//     waited for and a refused write stops that Tag (ADR 0004);
//   - a local config the server's configuration cannot satisfy — a Tag the
//     Device does not supply, a pattern that does not fit its Tag, an
//     Environment the project does not have — is ExitConfig;
//   - anything else (a TLS or URL scheme error, another 4xx) is a protocol
//     error.
//
// Transient failures (network, 5xx) are retried before they get here; the
// mapping keeps one that escapes from reading as a protocol error.
func exitCode(err error) int {
	switch {
	case devicelink.IsNoPermission(err):
		return gracedown.ExitNoPerm
	case errors.Is(err, devicesim.ErrConfig), errors.Is(err, devicesim.ErrEnvironmentNotFound):
		return gracedown.ExitConfig
	case devicelink.IsTransient(err):
		return gracedown.ExitTempFail
	default:
		return gracedown.ExitProtocol
	}
}

// readConfig reads the config file and applies the flags over it, then
// validates: a secret may come from the environment alone, with no token in
// the file at all.
func readConfig(path string, args simulatorArgs) (devicesim.Config, error) {
	f, err := os.Open(path)
	if err != nil {
		return devicesim.Config{}, err
	}
	defer f.Close()
	cfg, err := devicesim.ParseConfig(f)
	if err != nil {
		return devicesim.Config{}, err
	}
	if args.Server != "" {
		cfg.Server = args.Server
	}
	if args.Token != "" {
		cfg.Token = args.Token
	}
	if args.Control != "" {
		cfg.Control = args.Control
	}
	if err := cfg.Validate(); err != nil {
		return devicesim.Config{}, err
	}
	return cfg, nil
}

// emergencyExit shuts down all registered components and exits with the given code.
func emergencyExit(manager *gracedown.Manager, exitCode int) {
	if shutdownErr := manager.EmergencyShutdown(); shutdownErr != nil {
		slog.Error("Emergency shutdown error", "error", shutdownErr)
	}
	os.Exit(exitCode)
}
